import{_ as i,o as a,c as o,a2 as r}from"./chunks/framework.CdjpmwdR.js";const h=JSON.parse('{"title":"Diagram-First Thinking: Making Thought Processes Visible","description":"Transforms diagrams into a thinking tool with a four-step method—reproduce, diverge, converge, recombine—to build reusable cognitive structures.","frontmatter":{"category":"mesh","date":"2024-01-01","title":"Diagram-First Thinking: Making Thought Processes Visible","description":"Transforms diagrams into a thinking tool with a four-step method—reproduce, diverge, converge, recombine—to build reusable cognitive structures.","tags":["mesh","architecture","engineering-practice","methodology"],"image":""},"headers":[],"relativePath":"en/blogs/2024/202401-illustrations.md","filePath":"en/blogs/2024/202401-illustrations.md"}'),t={name:"en/blogs/2024/202401-illustrations.md"};function n(s,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<p>After summarizing architecture diagram practices in a previous post, I started to use &quot;diagrams&quot; beyond technical communication – for everyday learning and problem analysis.</p><p>With more practice, I noticed that different diagram types map to different <strong>cognitive moves</strong>:</p><ul><li>Mind maps are good at decomposition</li><li>Sequence diagrams are good at reconstructing processes</li><li>Structural diagrams are good at finding boundaries</li></ul><p>Pick the right diagram, and your thinking speed improves significantly.</p><h2 id="diagramming-as-visualized-thinking" tabindex="-1">Diagramming as Visualized Thinking <a class="header-anchor" href="#diagramming-as-visualized-thinking" aria-label="Permalink to &quot;Diagramming as Visualized Thinking&quot;">​</a></h2><p>Compared to invisible mental operations, drawing your thinking as diagrams is much clearer and easier to revisit:</p><ul><li>You externalize and record your reasoning process</li><li>You (and others) can replay and critique it later</li></ul><p>Modern tools and templates help a lot: whiteboards, versioning, diagram‑as‑code, layers… For many tasks, sketching a diagram is now <strong>faster than typing</strong>.</p><h2 id="a-four-step-loop" tabindex="-1">A Four-Step Loop <a class="header-anchor" href="#a-four-step-loop" aria-label="Permalink to &quot;A Four-Step Loop&quot;">​</a></h2><p>To make diagramming usable in many contexts, I use a simple four‑step loop. Diagramming is just one expression channel; thinking still comes first.</p><h3 id="_1-reproduce" tabindex="-1">1. Reproduce <a class="header-anchor" href="#_1-reproduce" aria-label="Permalink to &quot;1. Reproduce&quot;">​</a></h3><p>Dump what’s in your head onto the whiteboard.</p><blockquote><p>Like a brain dump: capture <strong>everything</strong> without filtering. <br> This frees up working memory and makes later steps easier.</p></blockquote><h3 id="_2-diverge" tabindex="-1">2. Diverge <a class="header-anchor" href="#_2-diverge" aria-label="Permalink to &quot;2. Diverge&quot;">​</a></h3><p>Expand around current information:</p><ul><li>What’s missing?</li><li>What extra notes or clarifications are needed?</li><li>What relationships exist – time, dependency, composition?</li></ul><blockquote><p>Pull in external sources here if useful – interviews, search, prior docs.</p></blockquote><h3 id="_3-converge" tabindex="-1">3. Converge <a class="header-anchor" href="#_3-converge" aria-label="Permalink to &quot;3. Converge&quot;">​</a></h3><p>Focus and clean up:</p><ul><li><strong>Semantic convergence</strong>: use abbreviations, symbols, colors to encode types and meanings</li><li><strong>Logical convergence</strong>: use distance, direction and shapes to encode structure and relationships</li><li>Identify the <strong>key information</strong></li></ul><blockquote><p>This step forces another round of thinking and retrieval. <br> You compress noise into structure.</p></blockquote><h3 id="_4-recombine" tabindex="-1">4. Recombine <a class="header-anchor" href="#_4-recombine" aria-label="Permalink to &quot;4. Recombine&quot;">​</a></h3><p>Using the converged key information as anchors, pick the right <strong>diagram type</strong> and redraw.</p><blockquote><p>After convergence you usually know <em>what kind</em> of diagram fits best. <br> Conversely, the constraints of a diagram type can drive deeper thinking.</p></blockquote><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Some of the tooling I use:</p><blockquote><p>Diagram tooling repo: <a href="https://github.com/Anddd7/docs-architecture-diagrams" target="_blank" rel="noreferrer">https://github.com/Anddd7/docs-architecture-diagrams</a></p></blockquote><ul><li>Whiteboards (Miro / Excalidraw)</li><li>Diagram‑as‑code (Mermaid, D2, PlantUML)</li><li>Cloud diagrams, infra views, business flows, etc.</li></ul><p>The tools themselves are secondary. The core is: <strong>treat drawing as part of thinking, not post‑hoc decoration</strong>.</p>',29)])])}const p=i(t,[["render",n]]);export{h as __pageData,p as default};
